<?php
declare(strict_types=1);$active_module='hotel_mobile';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';
if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??''))){$id=(int)$_POST['task_id'];$status=$_POST['status']==='completed'?'completed':'in_progress';$q=$pdo->prepare('SELECT h.physical_room_id FROM housekeeping_tasks h JOIN properties p ON p.id=h.property_id WHERE h.id=? AND p.supplier_id=?');$q->execute([$id,$u['supplier_id']]);$task=$q->fetch();if($task){$pdo->prepare("UPDATE housekeeping_tasks SET status=?,completed_at=CASE WHEN ?='completed' THEN now() ELSE NULL END WHERE id=?")->execute([$status,$status,$id]);if($status==='completed'&&$task['physical_room_id'])$pdo->prepare("UPDATE physical_rooms SET status='inspected' WHERE id=?")->execute([$task['physical_room_id']]);$message='Görev güncellendi.';}}
$q=$pdo->prepare("SELECT h.*,p.name property_name,pr.room_number FROM housekeeping_tasks h JOIN properties p ON p.id=h.property_id LEFT JOIN physical_rooms pr ON pr.id=h.physical_room_id WHERE p.supplier_id=? AND h.status NOT IN ('completed','inspected') ORDER BY CASE h.priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 ELSE 2 END,h.created_at");$q->execute([$u['supplier_id']]);$tasks=$q->fetchAll();supply_start('Kat hizmetleri mobil pano',$active_module);?><section class="page-intro"><p>Telefon/tablet için sade görev panosu. Temizlik tamamlanınca oda kontrol bekliyor durumuna geçer.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><section class="next-module"><?php foreach($tasks as $t):?><article><h2><?=htmlspecialchars($t['property_name'])?> · Oda <?=htmlspecialchars($t['room_number']??'Genel alan')?></h2><p><?=htmlspecialchars($t['task_type'])?> · <?=htmlspecialchars($t['priority'])?> · <?=htmlspecialchars($t['assigned_to']??'Atanmadı')?></p><p><?=htmlspecialchars($t['notes']??'')?></p><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="task_id" value="<?=$t['id']?>"><button name="status" value="in_progress">Başla</button><button name="status" value="completed">Tamamla / kontrole gönder</button></form></article><?php endforeach;?></section><?php supply_end();
